--- a/sdk/typescript/src/credentials/envelope.ts
+++ b/sdk/typescript/src/credentials/envelope.ts
@@ -1,5 +1,14 @@
+export type CredentialEnvelope = { token: string; expires_at?: string; source?: string };
+export function normalizeCredential(raw: any): CredentialEnvelope {
+  if (typeof raw === 'string') return { token: raw, source: 'legacy' };
+  return { token: raw.token, expires_at: raw.expires_at, source: raw.source ?? 'unknown' };
+}

--- a/sdk/go/credentials/envelope.go
+++ b/sdk/go/credentials/envelope.go
@@ -1,4 +1,18 @@
+type CredentialEnvelope struct {
+    Token     string `json:"token"`
+    ExpiresAt string `json:"expires_at,omitempty"`
+    Source    string `json:"source,omitempty"`
+}
+
+func NormalizeCredential(raw interface{}) CredentialEnvelope {
+    switch v := raw.(type) {
+    case string:
+        return CredentialEnvelope{Token: v, Source: "legacy"}
+    case map[string]interface{}:
+        return CredentialEnvelope{Token: v["token"].(string)}
+    default:
+        return CredentialEnvelope{Token: "", Source: "unknown"}
+    }
+}
